    { const char * tb_v1675 = "    p += n;\n"; *(const char * *)tb_grow(v_lines) = tb_v1675; }
    { const char * tb_v1676 = "    left -= n;\n"; *(const char * *)tb_grow(v_lines) = tb_v1676; }
    { const char * tb_v1677 = "    memset(r, 0, n);\n"; *(const char * *)tb_grow(v_lines) = tb_v1677; }
    { const char * tb_v1678 = "    return r;\n"; *(const char * *)tb_grow(v_lines) = tb_v1678; }
    { const char * tb_v1679 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v1679; }
    { const char * tb_v1680 = "// ---------- obj: память пачкой ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v1680; }
    { const char * tb_v1681 = "// obj никогда не отдают по одному (нет free), поэтому их не надо брать через malloc\n"; *(const char * *)tb_grow(v_lines) = tb_v1681; }
    { const char * tb_v1682 = "// поштучно: берём кусок на тысячи объектов и раздаём подряд. Быстрее, и соседние\n"; *(const char * *)tb_grow(v_lines) = tb_v1682; }
    { const char * tb_v1683 = "// объекты лежат рядом в памяти. Внутри temp и шага цикла — как раньше, из временной памяти.\n"; *(const char * *)tb_grow(v_lines) = tb_v1683; }
    { const char * tb_v1684 = "static void *tb_obj_mem(long long n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v1684; }
    { const char * tb_v1685 = "    if (tb_temp_depth > 0) return tb_mem(n);\n"; *(const char * *)tb_grow(v_lines) = tb_v1685; }
    { const char * tb_v1686 = "    static _Thread_local char *p = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v1686; }
    { const char * tb_v1687 = "    static _Thread_local long long left = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v1687; }
    { const char * tb_v1688 = "    n = (n + 7) & ~7LL;\n"; *(const char * *)tb_grow(v_lines) = tb_v1688; }
    { const char * tb_v1689 = "    if (left < n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v1689; }
    { const char * tb_v1690 = "        long long size = n > (1LL << 20) ? n : (1LL << 20);\n"; *(const char * *)tb_grow(v_lines) = tb_v1690; }
    { const char * tb_v1691 = "        p = malloc(size);\n"; *(const char * *)tb_grow(v_lines) = tb_v1691; }
    { const char * tb_v1692 = "        if (!p) tb_crash(0, \"не хватило памяти\");\n"; *(const char * *)tb_grow(v_lines) = tb_v1692; }
    { const char * tb_v1693 = "        left = size;\n"; *(const char * *)tb_grow(v_lines) = tb_v1693; }
    { const char * tb_v1694 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v1694; }
    { const char * tb_v1695 = "    void *r = p;\n"; *(const char * *)tb_grow(v_lines) = tb_v1695; }
    { const char * tb_v1696 = "    p += n;\n"; *(const char * *)tb_grow(v_lines) = tb_v1696; }
    { const char * tb_v1697 = "    left -= n;\n"; *(const char * *)tb_grow(v_lines) = tb_v1697; }
    { const char * tb_v1698 = "    return r;\n"; *(const char * *)tb_grow(v_lines) = tb_v1698; }
    { const char * tb_v1699 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v1699; }
    { const char * tb_v1700 = "// ---------- background: работа в своём потоке ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v1700; }
    { const char * tb_v1701 = "#ifndef TB_BARE\n"; *(const char * *)tb_grow(v_lines) = tb_v1701; }
    { const char * tb_v1702 = "typedef struct { pthread_t th; int done; void *res; } tb_task;\n"; *(const char * *)tb_grow(v_lines) = tb_v1702; }
    { const char * tb_v1703 = "static void tb_task_start(tb_task *t, void *(*run)(void *), void *arg) {\n"; *(const char * *)tb_grow(v_lines) = tb_v1703; }
    { const char * tb_v1704 = "    t->done = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v1704; }
    { const char * tb_v1705 = "    if (pthread_create(&t->th, 0, run, arg) != 0) tb_crash(0, \"не получилось запустить background\");\n"; *(const char * *)tb_grow(v_lines) = tb_v1705; }
    { const char * tb_v1706 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v1706; }
    { const char * tb_v1707 = "// a.wait: дождаться потока (один раз) и отдать адрес ответа\n"; *(const char * *)tb_grow(v_lines) = tb_v1707; }
    { const char * tb_v1708 = "static void *tb_wait(tb_task *t) {\n"; *(const char * *)tb_grow(v_lines) = tb_v1708; }
    { const char * tb_v1709 = "    if (!t->done) { pthread_join(t->th, 0); t->done = 1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v1709; }
    { const char * tb_v1710 = "    return t->res;\n"; *(const char * *)tb_grow(v_lines) = tb_v1710; }
    { const char * tb_v1711 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v1711; }
    { const char * tb_v1712 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v1712; }
    { const char * tb_v1713 = "static int tb_dhas(tb_dict *d, const void *k) { return tb_dfind(d, k) >= 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v1713; }
    { const char * tb_v1714 = "static void tb_dremove(tb_dict *d, const void *k) {\n"; *(const char * *)tb_grow(v_lines) = tb_v1714; }
    { const char * tb_v1715 = "    long long at = tb_dfind(d, k);\n"; *(const char * *)tb_grow(v_lines) = tb_v1715; }
    { const char * tb_v1716 = "    if (at < 0) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v1716; }
    { const char * tb_v1717 = "    if (d->mode != 0) tb_dto_hash(d);\n"; *(const char * *)tb_grow(v_lines) = tb_v1717; }
    { const char * tb_v1718 = "    long long last = d->keys->len - 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v1718; }
    { const char * tb_v1719 = "    // на место удалённого ставим последний: порядок меняется только у него\n"; *(const char * *)tb_grow(v_lines) = tb_v1719; }
    { const char * tb_v1720 = "    memcpy(d->keys->data + at * d->keys->size, d->keys->data + last * d->keys->size, d->keys->size);\n"; *(const char * *)tb_grow(v_lines) = tb_v1720; }
    { const char * tb_v1721 = "    memcpy(d->vals->data + at * d->vals->size, d->vals->data + last * d->vals->size, d->vals->size);\n"; *(const char * *)tb_grow(v_lines) = tb_v1721; }
    { const char * tb_v1722 = "    d->keys->len -= 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v1722; }
